/** Real native UI, persistence, provider callbacks and parser boundaries on disposable emulators. */
public final class GadgetSmoke extends AeroSmoke {
    private MainActivity activity;private View root;private boolean ownSuite;
    private final BlockingQueue<MainActivity> resumed=new LinkedBlockingQueue<>();
    private final Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){if(a instanceof MainActivity)resumed.offer((MainActivity)a);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityStopped(Activity a){}public void onActivityPaused(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
    @Override public void onCreate(Bundle args){ownSuite=args==null||args.getString("suite")==null;super.onCreate(args);}
    @Override public void onStart(){if(!ownSuite){super.onStart();return;}Bundle result=new Bundle();Application application=(Application)getTargetContext().getApplicationContext();application.registerActivityLifecycleCallbacks(lifecycle);try{
        DesktopStore store=new DesktopStore(getTargetContext());getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putInt("boot",StartupExperience.boot(getTargetContext())).commit();store.prefs.edit().putBoolean("weather_follow",false).remove("gadget_data").remove("feed_url").remove("feed_items").commit();
        Intent intent=new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=(MainActivity)startActivitySync(intent);root=activity.getWindow().getDecorView();Thread.sleep(300);
        gallery(store);tools(store);parsers(store);location(store);result.putString("stream","PASS: fourteen searchable native gadgets, distinct real window icons, calculator and conversions, checklist actions, live stopwatch/laps/countdown, world zones, actual storage, RSS/Atom parsing, gadget backup validation, activity recreation, and Android fused/network mock-location follow/pause/resume with stale-fix rejection.\n");application.unregisterActivityLifecycleCallbacks(lifecycle);finish(Activity.RESULT_OK,result);
    }catch(Throwable failure){try{shot("gadgets-failure.png");}catch(Exception ignored){}java.io.StringWriter text=new java.io.StringWriter();failure.printStackTrace(new java.io.PrintWriter(text));result.putString("stream","FAIL: "+text+"\n");application.unregisterActivityLifecycleCallbacks(lifecycle);finish(Activity.RESULT_CANCELED,result);}}
    private void gallery(DesktopStore store)throws Exception{
        progress("checking the expanded searchable gadget gallery");ui(()->activity.open("@gadgets"));await(v->"Search Gadget Gallery".equals(v.getContentDescription()));EditText search=(EditText)find(v->"Search Gadget Gallery".equals(v.getContentDescription()));ui(()->search.setText("Countdown"));check(find(v->"Details for Countdown gadget".equals(v.getContentDescription()))!=null,"Gallery search finds the countdown");check(find(v->"Details for Clock gadget".equals(v.getContentDescription()))==null,"Gallery search filters other gadgets");ui(()->search.setText(""));check(GadgetCatalog.IDS.length==14,"Fourteen actual gadget types are available");for(String id:GadgetCatalog.IDS){String title=GadgetCatalog.title(id);check(find(v->("Details for "+title+" gadget").equals(v.getContentDescription()))!=null,"Gallery includes details for "+id);if(!store.gadgets().contains(id))click("@gadgets","Add "+title+" gadget");}check(store.gadgets().size()==14,"All fourteen gadgets can actually be enabled");shot("gadget-gallery-expanded.png");
        JSONObject backup=DesktopBackup.snapshot(store);check(DesktopBackup.parse(backup.toString()).count("gadgets")==14,"Backups accept all new gadget types and layouts");click("@gadgets","Close window");shot("gadget-pack-desktop.png");
        Set<Long> images=new HashSet<>();for(String id:new String[]{"@clock","@calendar","@weather","@sticky","@gadgets"}){ui(()->activity.open(id));DesktopWindow tool=tool(id);check(tool!=null,"Gadget window opens: "+id);View icon=((ViewGroup)tool.getChildAt(0)).getChildAt(0);Bitmap bitmap=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);ui(()->{Canvas canvas=new Canvas(bitmap);canvas.scale(64f/Math.max(1,icon.getWidth()),64f/Math.max(1,icon.getHeight()));icon.draw(canvas);});long hash=1;for(int y=0;y<64;y++)for(int x=0;x<64;x++)hash=hash*31+bitmap.getPixel(x,y);bitmap.recycle();check(images.add(hash),"Each real gadget window paints a distinct caption icon: "+id);click(id,"Close window");}
    }
    private void tools(DesktopStore store)throws Exception{
        progress("checking working native calculator, converter, checklist and time tools");open("calculator");EditText expression=(EditText)find(v->"Calculator expression".equals(v.getContentDescription()));ui(()->expression.setText("(12+8)*3"));click("@gadget:calculator","Calculator =");check("60".contentEquals(((TextView)find(v->"Calculator result".equals(v.getContentDescription()))).getText()),"Calculator evaluates real arithmetic");shot("gadget-calculator.png");click("@gadget:calculator","Close window");
        open("converter");EditText input=(EditText)find(v->"Value to convert".equals(v.getContentDescription()));ui(()->input.setText("1000"));await(v->"Conversion result".equals(v.getContentDescription())&&((TextView)v).getText().toString().equals("1 km"));shot("gadget-converter.png");click("@gadget:converter","Close window");
        open("checklist");EditText task=(EditText)find(v->"New checklist item".equals(v.getContentDescription()));ui(()->task.setText("A saved gadget task"));click("@gadget:checklist","Add checklist item");click("@gadget:checklist","Checklist task: A saved gadget task");check(GadgetData.get(store,"checklist").getJSONArray("tasks").getJSONObject(0).getBoolean("done"),"Checklist checkbox changes saved data");shot("gadget-checklist.png");click("@gadget:checklist","Clear completed tasks");check(GadgetData.get(store,"checklist").getJSONArray("tasks").length()==0,"Completed tasks can be removed");click("@gadget:checklist","Close window");
        open("stopwatch");click("@gadget:stopwatch","Start stopwatch");Thread.sleep(1150);check(GadgetData.value(store,"stopwatch")>=1000,"Stopwatch measures actual elapsed time");click("@gadget:stopwatch","Save lap");check(GadgetData.get(store,"stopwatch").getJSONArray("laps").length()==1,"A lap is saved");click("@gadget:stopwatch","Pause stopwatch");long paused=GadgetData.value(store,"stopwatch");Thread.sleep(150);check(paused==GadgetData.value(store,"stopwatch"),"Paused stopwatch is stable");shot("gadget-stopwatch.png");click("@gadget:stopwatch","Close window");
        open("timer");EditText minutes=(EditText)find(v->"Countdown minutes".equals(v.getContentDescription()));ui(()->minutes.setText("1"));click("@gadget:timer","Start or resume countdown");Thread.sleep(250);check(GadgetData.value(store,"timer")>57000&&GadgetData.value(store,"timer")<60000,"Countdown runs from the chosen duration");click("@gadget:timer","Pause countdown");long remaining=GadgetData.value(store,"timer");Thread.sleep(150);check(remaining==GadgetData.value(store,"timer"),"Countdown pause preserves the remaining time");shot("gadget-countdown.png");click("@gadget:timer","Close window");
        open("worldclock");Spinner zone=(Spinner)find(v->"World clock zone 1".equals(v.getContentDescription()));int index=-1;for(int i=0;i<zone.getCount();i++)if("America/New_York".equals(zone.getItemAtPosition(i)))index=i;check(index>=0,"Available time zones are real Android zones");int selected=index;ui(()->zone.setSelection(selected));await(v->"World clock times".equals(v.getContentDescription())&&((TextView)v).getText().toString().contains("America/New York"));check(GadgetData.get(store,"worldclock").optString("zone2","Asia/Tokyo").equals("Asia/Tokyo"),"The second world zone is independent");shot("gadget-world-clock.png");click("@gadget:worldclock","Close window");
        open("storage");check(((TextView)find(v->"Internal storage readings".equals(v.getContentDescription()))).getText().toString().contains("available"),"Storage shows real StatFs readings");click("@gadget:storage","Close window");
        JSONObject backup=DesktopBackup.snapshot(store);DesktopBackup.Plan plan=DesktopBackup.parse(backup.toString());check(new JSONObject(plan.string("gadget_data","{}")).getJSONObject("calculator").getString("result").equals("60"),"Gadget content is included in backups");JSONObject old=new JSONObject(backup.toString());old.getJSONObject("settings").remove("gadget_data");old.getJSONObject("settings").remove("weather_follow");old.getJSONObject("settings").remove("feed_url");check(DesktopBackup.parse(old.toString())!=null,"Existing 0.7 backups remain readable");JSONObject bad=new JSONObject(backup.toString());bad.getJSONObject("settings").put("gadget_data",new JSONObject().put("type","string").put("value","{\"worldclock\":{\"zone1\":\"not-a-zone\"}}"));boolean rejected=false;try{DesktopBackup.parse(bad.toString());}catch(JSONException expected){rejected=true;}check(rejected,"Invalid gadget settings cannot be restored");
        open("calculator");MainActivity previous=activity;resumed.clear();runOnMainSync(()->activity.recreate());replacement(previous);check("60".contentEquals(((TextView)find(v->"Calculator result".equals(v.getContentDescription()))).getText()),"Gadget window and contents survive recreation");click("@gadget:calculator","Close window");
    }
    private void parsers(DesktopStore store)throws Exception{
        progress("checking real RSS/Atom and place-search response formats");String rss="<rss version='2.0'><channel><title>Fixture</title><item><title>A working headline</title><link>https://example.org/article</link></item><item><title>Unsafe link</title><link>javascript:alert(1)</link></item></channel></rss>";JSONArray items=FeedClient.parse(rss,"https://example.org/feed");check(items.length()==1&&items.getJSONObject(0).getString("title").equals("A working headline"),"RSS parses titles and safe article links");JSONArray atom=FeedClient.parse("<feed xmlns='http://www.w3.org/2005/Atom'><entry><title>Atom headline</title><link href='/atom-article'/></entry></feed>","https://example.org/feed");check(atom.length()==1&&atom.getJSONObject(0).getString("url").equals("https://example.org/atom-article"),"Atom links resolve relative to the feed");boolean rejected=false;try{FeedClient.parse("<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///data/local/private'>]><rss/>","https://example.org");}catch(Exception expected){rejected=true;}check(rejected,"Feed parser rejects document declarations");check(!FeedClient.validUrl("file:///etc/hosts")&&!FeedClient.validUrl("https://user:password@example.org/feed"),"Feed configuration requires a plain HTTPS address");store.prefs.edit().putString("feed_items",items.toString()).commit();open("feeds");check(find(v->"A working headline".equals(v.getContentDescription()))!=null,"Actual parsed feed items appear in the native reader");shot("gadget-headlines.png");click("@gadget:feeds","Close window");
        java.util.List<CitySearch.Place> places=CitySearch.parse("{\"features\":[{\"geometry\":{\"coordinates\":[-70.2553,43.6615]},\"properties\":{\"name\":\"Portland\",\"state\":\"Maine\",\"country\":\"United States\"}}]}");check(places.size()==1&&places.get(0).label.contains("Maine")&&Math.abs(places.get(0).latitude-43.6615)<.001,"City search shows real provider labels and coordinates");
        JSONObject timer=new JSONObject().put("running",true).put("remaining",60000).put("start_wall",100000).put("start_elapsed",5000).put("boot",7);check(GadgetData.remaining(timer,110000,15000,7)==50000,"Countdown uses monotonic time within a boot");check(GadgetData.remaining(timer,120000,1000,8)==40000,"Countdown has a wall-clock fallback after reboot");check(GadgetData.remaining(timer,500000,1000,8)==0,"Expired countdown cannot become negative");
    }
    private void location(DesktopStore store)throws Exception{
        progress("checking actual Android fused location callbacks and foreground follow lifecycle");shell("cmd location set-location-enabled true");shell("pm grant com.nthexperience.desktop android.permission.ACCESS_COARSE_LOCATION");shell("appops set com.nthexperience.desktop android:mock_location allow");LocationManager manager=getTargetContext().getSystemService(LocationManager.class);check(manager!=null,"Android location service exists");WeatherClient client=new WeatherClient(store,()->{});WeatherLocation[] tracker=new WeatherLocation[1];String provider=Build.VERSION.SDK_INT>=31?"fused":LocationManager.NETWORK_PROVIDER;
        try{ui(()->{manager.addTestProvider(provider,false,false,false,false,false,false,false,Criteria.POWER_LOW,Criteria.ACCURACY_COARSE);manager.setTestProviderEnabled(provider,true);store.prefs.edit().putBoolean("weather_follow",true).remove("weather_lat").remove("weather_lon").commit();tracker[0]=new WeatherLocation(activity,store,client,()->true,()->{});tracker[0].resume();});progress("Location fixture: provider="+provider+", enabled="+manager.isProviderEnabled(provider)+", registered="+tracker[0].watching()+", status="+tracker[0].status());Location fix=fix(43.66,-70.25);ui(()->manager.setTestProviderLocation(provider,fix));awaitPreference(()->store.prefs.contains("weather_lat")&&Math.abs(Double.parseDouble(store.prefs.getString("weather_lat","0"))-43.66)<.2,"A fresh fused fix configures weather without a network-provider timeout");double first=Double.parseDouble(store.prefs.getString("weather_lat","0"));check(Math.abs(first-43.66)<.2,"Weather receives the permitted approximate area");ui(()->tracker[0].pause());check(!tracker[0].watching(),"Leaving Home removes all location requests");ui(()->tracker[0].resume());check(tracker[0].watching(),"Following reattaches actual location requests when Home resumes");check(store.prefs.contains("weather_lat"),"A usable saved area remains available while waiting for Android’s next update");ui(()->{tracker[0].stopFollowing();store.prefs.edit().putBoolean("weather_follow",false).remove("weather_lat").remove("weather_lon").commit();tracker[0].locate();});awaitPreference(()->store.prefs.contains("weather_lat"),"The one-time location action can immediately use a recent fused fix");Location stale=fix(40,-74);check(!WeatherLocation.usable(stale,SystemClock.elapsedRealtimeNanos()+7200000000000L,System.currentTimeMillis()+7200000,1800000L),"A stale cached fix is rejected");Location inaccurate=fix(40,-74);inaccurate.setAccuracy(100000);check(!WeatherLocation.usable(inaccurate,SystemClock.elapsedRealtimeNanos(),System.currentTimeMillis(),1800000L),"An unusably imprecise cached fix is rejected");ui(()->tracker[0].stopFollowing());check(!tracker[0].watching(),"Turning follow off stops requests");
        }finally{ui(()->{if(tracker[0]!=null)tracker[0].close();client.close();try{manager.removeTestProvider(provider);}catch(RuntimeException ignored){}store.prefs.edit().putBoolean("weather_follow",false).commit();});shell("appops set com.nthexperience.desktop android:mock_location default");}
        ui(()->activity.open("@weather"));check(find(v->"Follow my location".equals(v.getContentDescription()))!=null,"Weather settings expose the follow option");shot("weather-follow-settings.png");click("@weather","Close window");
    }
    private Location fix(double lat,double lon){Location fix=new Location(Build.VERSION.SDK_INT>=31?"fused":LocationManager.NETWORK_PROVIDER);fix.setLatitude(lat);fix.setLongitude(lon);fix.setAccuracy(1000);fix.setTime(System.currentTimeMillis());fix.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());return fix;}
    private void open(String kind)throws Exception{ui(()->activity.gadgetAction(kind));await(v->v instanceof DesktopWindow&&("@gadget:"+kind).equals(((DesktopWindow)v).toolId));}
    private DesktopWindow tool(String id){return (DesktopWindow)find(v->v instanceof DesktopWindow&&id.equals(((DesktopWindow)v).toolId));}
    private void click(String id,String label)throws Exception{View view=find(id==null?root:tool(id),v->label.equals(v.getContentDescription()));check(view!=null,"Native action exists: "+label);ui(view::performClick);}
    private void replacement(MainActivity before)throws Exception{long end=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<end){MainActivity next=resumed.poll(1,TimeUnit.SECONDS);if(next!=null&&next!=before&&!next.isDestroyed()){activity=next;root=next.getWindow().getDecorView();Thread.sleep(180);return;}}throw new AssertionError("Activity recreation did not finish");}
    private void await(Predicate<View> condition)throws Exception{awaitPreference(()->find(condition)!=null,"Expected native gadget UI appears");}
    private void awaitPreference(java.util.function.BooleanSupplier condition,String message)throws Exception{long end=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<end){java.util.concurrent.atomic.AtomicBoolean ok=new java.util.concurrent.atomic.AtomicBoolean();runOnMainSync(()->ok.set(condition.getAsBoolean()));if(ok.get())return;Thread.sleep(80);}throw new AssertionError(message);}
    private View find(Predicate<View> condition){return find(root,condition);}
    private View find(View view,Predicate<View> condition){if(view==null||!view.isShown())return null;if(condition.test(view))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=find(((ViewGroup)view).getChildAt(i),condition);if(found!=null)return found;}return null;}
    private void ui(Runnable action){runOnMainSync(action);try{Thread.sleep(65);}catch(InterruptedException ex){Thread.currentThread().interrupt();throw new AssertionError(ex);}}
    private void shot(String name)throws Exception{Thread.sleep(350);Bitmap bitmap=getUiAutomation().takeScreenshot();check(bitmap!=null,"Screenshot available");try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getFilesDir(),name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}finally{bitmap.recycle();}}
    private String shell(String command)throws Exception{try(android.os.ParcelFileDescriptor descriptor=getUiAutomation().executeShellCommand(command);java.io.InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(descriptor);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] bytes=new byte[2048];int count;while((count=in.read(bytes))!=-1)out.write(bytes,0,count);return out.toString("UTF-8");}}
    private void progress(String message){Bundle status=new Bundle();status.putString("stream","CHECK: "+message+"\n");sendStatus(1,status);}
    private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
}
